WITH valid AS (SELECT id, supplier_name, country, city, rating, COALESCE(rating, 0) AS rating_filled, COALESCE(city, 'UNKNOWN') AS city_filled FROM suppliers WHERE supplier_name LIKE 'Li%') SELECT CASE WHEN rating_filled >= 64 THEN 'LARGE' ELSE 'SMALL' END AS rating_filled_tier, ROUND(AVG(rating_filled), 2) AS avg_rating_filled, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, COUNT(DISTINCT id) AS distinct_ids, STDDEV_SAMP(rating) AS rating_stddev FROM valid GROUP BY ROLLUP (CASE WHEN rating_filled >= 64 THEN 'LARGE' ELSE 'SMALL' END);
